"use client"

import { useState } from "react"
import { ChevronLeft, ChevronRight, Home, BookOpen, Bell, Clock, AlertTriangle } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"

interface MedicationReminderPageProps {
  onNavigate: (page: "home" | "edukasi") => void
}

export function MedicationReminderPage({ onNavigate }: MedicationReminderPageProps) {
  const [currentMonth, setCurrentMonth] = useState(new Date(2024, 2)) // March 2024
  const [selectedDate, setSelectedDate] = useState(15)

  // Calendar data
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate()
  const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay()
  const monthNames = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ]

  const previousMonthDays = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 0).getDate()
  const daysFromPrevMonth = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1

  const calendarDays = []

  // Previous month days
  for (let i = daysFromPrevMonth; i > 0; i--) {
    calendarDays.push({
      day: previousMonthDays - i + 1,
      isCurrentMonth: false,
      isToday: false,
      isSelected: false,
    })
  }

  // Current month days with reminder indicators
  for (let i = 1; i <= daysInMonth; i++) {
    calendarDays.push({
      day: i,
      isCurrentMonth: true,
      isToday: i === 15,
      isSelected: i === selectedDate,
      hasReminder: [15, 16, 17, 18, 24, 25].includes(i), // Days with reminders
    })
  }

  // Next month days to fill the grid
  const remainingDays = 35 - calendarDays.length
  for (let i = 1; i <= remainingDays; i++) {
    calendarDays.push({
      day: i,
      isCurrentMonth: false,
      isToday: false,
      isSelected: false,
    })
  }

  const handlePrevMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1))
  }

  const handleNextMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1))
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-50/50 to-white relative">
      <div className="max-w-md mx-auto px-4 py-6 pb-24">
        <div className="mb-6">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => onNavigate("home")}
            className="mb-4 text-muted-foreground hover:text-foreground"
          >
            <ChevronLeft className="w-5 h-5" />
          </Button>
          <div className="text-center">
            <h1 className="text-xl font-bold text-blue-600 mb-1">Fase: Intensif</h1>
            <p className="text-sm text-muted-foreground">(Hari ke-18 dari 60)</p>
          </div>
        </div>

        <Card className="mb-6 border-0 shadow-sm bg-white">
          <CardContent className="p-5">
            {/* Month Header */}
            <div className="flex items-center justify-between mb-5">
              <Button variant="ghost" size="icon" onClick={handlePrevMonth} className="h-8 w-8 hover:bg-gray-100">
                <ChevronLeft className="w-4 h-4 text-gray-600" />
              </Button>
              <h2 className="text-base font-bold text-gray-900">{monthNames[currentMonth.getMonth()].toUpperCase()}</h2>
              <Button variant="ghost" size="icon" onClick={handleNextMonth} className="h-8 w-8 hover:bg-gray-100">
                <ChevronRight className="w-4 h-4 text-gray-600" />
              </Button>
            </div>

            {/* Day Headers */}
            <div className="grid grid-cols-7 gap-1 mb-3">
              {["SU", "MO", "TU", "WE", "TH", "FR", "SA"].map((day) => (
                <div key={day} className="text-center text-xs font-medium text-gray-500 py-1">
                  {day}
                </div>
              ))}
            </div>

            {/* Calendar Grid with soft indicators */}
            <div className="grid grid-cols-7 gap-1">
              {calendarDays.map((dayInfo, index) => (
                <button
                  key={index}
                  onClick={() => dayInfo.isCurrentMonth && setSelectedDate(dayInfo.day)}
                  disabled={!dayInfo.isCurrentMonth}
                  className={`
                    relative aspect-square rounded-lg text-sm font-medium transition-all flex items-center justify-center
                    ${!dayInfo.isCurrentMonth ? "text-gray-300" : "text-gray-700"}
                    ${dayInfo.isToday ? "bg-red-500 text-white shadow-sm" : ""}
                    ${dayInfo.isSelected && !dayInfo.isToday ? "bg-blue-500 text-white shadow-sm" : ""}
                    ${dayInfo.hasReminder && !dayInfo.isToday && !dayInfo.isSelected ? "bg-green-100 text-green-700" : ""}
                    ${!dayInfo.isToday && !dayInfo.isSelected && !dayInfo.hasReminder && dayInfo.isCurrentMonth ? "hover:bg-gray-50" : ""}
                  `}
                >
                  {dayInfo.day}
                </button>
              ))}
            </div>
          </CardContent>
        </Card>

        <Card className="border-0 shadow-sm overflow-hidden">
          <div className="bg-gradient-to-br from-orange-400 via-orange-500 to-red-500 p-5 text-white">
            <h3 className="font-bold text-lg mb-1">Saatnya Minum Obat TBC hari ini</h3>
            <div className="mt-4 space-y-3 text-[13px]">
              <div>
                <p className="font-semibold mb-1">Obat:</p>
                <p className="leading-relaxed">Isoniazid, Rifampisin, Pirazinamid, Etambutol</p>
              </div>
              <div>
                <p className="font-semibold mb-1">Waktu:</p>
                <p className="text-2xl font-bold">09.00 Pagi</p>
              </div>
              <div className="flex items-center gap-2">
                <p className="font-semibold">Status:</p>
                <Badge variant="secondary" className="bg-white/20 text-white border-white/30 hover:bg-white/20">
                  <AlertTriangle className="w-3 h-3 mr-1" />
                  Belum diminum
                </Badge>
              </div>
            </div>
          </div>
          <CardContent className="p-4 space-y-3">
            <Button className="w-full bg-green-500 hover:bg-green-600 text-white font-semibold py-6 rounded-lg shadow-sm">
              <span className="text-base">✓ Sudah Minum</span>
            </Button>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" className="flex-1 text-xs h-9 rounded-lg bg-transparent">
                Ubah Alarm
              </Button>
              <Button variant="outline" size="sm" className="flex-1 text-xs h-9 rounded-lg bg-transparent">
                <Clock className="w-3 h-3 mr-1" />
                Tunda 15 menit
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 shadow-lg">
        <div className="max-w-md mx-auto px-4 py-3">
          <div className="flex items-center justify-around">
            <Button
              variant="ghost"
              onClick={() => onNavigate("home")}
              className="flex flex-col items-center gap-1 h-auto py-2 hover:bg-transparent"
            >
              <Home className="w-5 h-5 text-gray-400" />
              <span className="text-xs text-gray-400">Home</span>
            </Button>
            <Button
              variant="ghost"
              onClick={() => onNavigate("edukasi")}
              className="flex flex-col items-center gap-1 h-auto py-2 hover:bg-transparent"
            >
              <BookOpen className="w-5 h-5 text-gray-400" />
              <span className="text-xs text-gray-400">Edukasi</span>
            </Button>
            <Button variant="ghost" className="flex flex-col items-center gap-1 h-auto py-2 hover:bg-transparent">
              <Bell className="w-5 h-5 text-blue-500" />
              <span className="text-xs text-blue-500 font-medium">Reminder</span>
            </Button>
          </div>
        </div>
      </div>
    </div>
  )
}
